float nmod(float x, float y){return x - y*floor(x/y);}

float hash11(float p){
    p = fract(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

float hash12(vec2 p){
    p = fract(p * vec2(0.1031,0.0973));
    p += dot(p.xy, p.yx+33.33);
    return fract(p.x * p.y);
}

float hash13(vec3 p){
    p = fract(p*0.1031);
    p *= p+33.33;
    p *= p + vec3(p.y,p.z,p.x);
    return fract(p.x+p.y+p.z);
}

float noise3D(vec3 x){
    vec3 i = floor(x);
    vec3 f = fract(x);
    float n = i.x + i.y*57.0 + i.z*113.0;
    float a = hash11(n + 0.0);
    float b = hash11(n + 1.0);
    float c = hash11(n + 57.0);
    float d = hash11(n + 58.0);
    float e = hash11(n + 113.0);
    float g = hash11(n + 114.0);
    float h = hash11(n + 170.0);
    float k = hash11(n + 171.0);
    vec3 u = f*f*(3.0-2.0*f);
    float m1 = mix(a,b,u.x);
    float m2 = mix(c,d,u.x);
    float m3 = mix(e,g,u.x);
    float m4 = mix(h,k,u.x);
    float m12 = mix(m1,m2,u.y);
    float m34 = mix(m3,m4,u.y);
    return mix(m12,m34,u.z);
}

float noise2D(vec2 p){
    vec2 i = floor(p);
    vec2 f = fract(p);
    float a = hash12(i + vec2(0.0,0.0));
    float b = hash12(i + vec2(1.0,0.0));
    float c = hash12(i + vec2(0.0,1.0));
    float d = hash12(i + vec2(1.0,1.0));
    vec2 u = f*f*(3.0-2.0*f);
    return mix(mix(a,b,u.x), mix(c,d,u.x), u.y);
}

mat3 rotX(float a){
    float s=sin(a), c=cos(a);
    return mat3(
        1.0, 0.0, 0.0,
        0.0, c,   -s,
        0.0, s,    c
    );
}

mat3 rotY(float a){
    float s=sin(a), c=cos(a);
    return mat3(
        c,   0.0, s,
        0.0, 1.0, 0.0,
       -s,   0.0, c
    );
}

mat3 rotZ(float a){
    float s=sin(a), c=cos(a);
    return mat3(
        c, -s, 0.0,
        s,  c, 0.0,
        0.0,0.0,1.0
    );
}

vec3 applyTransform(vec3 p, float rotationAngle, vec3 shift) {
    p -= shift;
    p = rotZ(-radians(rotationAngle)) * p;
    return p;
}

float sdSphere(vec3 p, float r){
    return length(p) - r;
}

float sdTorusPerpY(vec3 p, vec2 t){
    vec2 q = vec2(length(p.xz) - t.x, p.y);
    return length(q) - t.y;
}

float sdCappedCylinder(vec3 p, float h, float r){
    vec2 d = abs(vec2(length(p.xz), p.y)) - vec2(r,h);
    return min(max(d.x,d.y), 0.0) + length(max(d,0.0));
}

float opUnion(float d1,float d2){
    return min(d1,d2);
}

float opSubtraction(float d1,float d2){
    return max(d1,-d2);
}

float smoothUnion(float d1, float d2, float k){
    float h = clamp(0.5+0.5*(d2-d1)/k, 0.0, 1.0);
    return mix(d2,d1,h) - k*h*(1.0-h);
}

float lollipopRing1(vec3 p){
    return sdTorusPerpY(p, vec2(0.45, 0.06));
}

float lollipopHead1(vec3 p){
    float s = sdSphere(p, 0.45);
    float ring = lollipopRing1(p);
    float merged = smoothUnion(s, ring, 0.05);
    float bite = sdSphere(p + vec3(-0.6,0.0,0.0), 0.18);
    return opSubtraction(merged, bite);
    return bite;
}

float lollipopStick1(vec3 p){
    p.y += 2.2;
    return sdCappedCylinder(p, 2.4, 0.05);
}

float lollipopSDF1(vec3 p) {
    //p = applyTransform(p, 1.0, vec3(0.15, 0.0, 0.0));

    float h = lollipopHead1(p);

    float s = lollipopStick1(p);
    return opUnion(h, s);
}

float lollipopRing2(vec3 p){
    return sdTorusPerpY(p, vec2(0.49, 0.09));
}

float lollipopHead2(vec3 p){
    float s = sdSphere(p, .545);
    float ring = lollipopRing2(p);
    float merged = smoothUnion(s, ring, 0.05);
    return merged;
    float bite = sdSphere(p + vec3(0.,-0.3,0.5), 0.48);
    float res = opSubtraction(merged, bite);
    bite = sdSphere(p + vec3(0.1,-0.3,0.5), 0.48);
    return opSubtraction(res, bite);
    res = opSubtraction(res, bite);
    bite = sdSphere(p + vec3(0.1,-0.2,0.495), 0.491948);
    res = opSubtraction(res, bite);
    bite = sdSphere(p-vec3(.1,0.84,.2), .685);

}

float lollipopStick2(vec3 p){
    p.y += 2.2;
    return sdCappedCylinder(p, 2.4, 0.07);
}

float lollipopSDF2(vec3 p){
    p -= vec3(1.4, 0.0, 0.0);
    float head = lollipopHead2(p);
    float stick = lollipopStick2(p);
    return opUnion(head, stick);
}

float sceneSDF(vec3 p){
    float l1 = lollipopSDF1(p);
    float l2 = lollipopSDF2(p);
    return min(l1, l2);
}

vec3 calcNormal(vec3 p){
    float e = 0.0005;
    vec3 x = vec3(e,0.0,0.0);
    vec3 y = vec3(0.0,e,0.0);
    vec3 z = vec3(0.0,0.0,e);
    float sx = sceneSDF(p+x) - sceneSDF(p-x);
    float sy = sceneSDF(p+y) - sceneSDF(p-y);
    float sz = sceneSDF(p+z) - sceneSDF(p-z);
    return normalize(vec3(sx, sy, sz));
}

float raymarch(vec3 ro, vec3 rd){
    float t=0.0;
    for(int i=0;i<200;i++){
        vec3 p=ro+rd*t;
        float d=sceneSDF(p);
        if(abs(d)<0.0001 || t>60.0) break;
        t += d*0.5;
    }
    if(t>20.0) t = -1.0;
    return t;
}

float secondaryRaymarch(vec3 ro, vec3 rd){
    float t=0.0;
    for(int i=0;i<80;i++){
        vec3 p=ro+rd*t;
        float d=sceneSDF(p);
        if(abs(d)<0.0001 || t>20.0) break;
        t += d*0.5;
    }
    if(t>20.0) t=-1.0;
    return t;
}

vec3 calcNormalManual(vec3 p){
    float e=0.0005;
    vec3 xx=vec3(e,0.0,0.0);
    vec3 yy=vec3(0.0,e,0.0);
    vec3 zz=vec3(0.0,0.0,e);
    float sx=sceneSDF(p+xx)-sceneSDF(p-xx);
    float sy=sceneSDF(p+yy)-sceneSDF(p-yy);
    float sz=sceneSDF(p+zz)-sceneSDF(p-zz);
    return normalize(vec3(sx,sy,sz));
}

vec3 reflectColor(vec3 ro, vec3 rd, vec3 n, vec3 p){
    vec3 r = reflect(rd,n);
    float tt = secondaryRaymarch(p + 0.001*n, r);
    if(tt<0.0) return vec3(0.4,0.4,0.4);
    vec3 sp = ro + r*tt;
    vec3 nn = calcNormalManual(sp);
    float d = dot(nn, vec3(0.0,1.0,0.0))*0.5 + 1.95;
    return vec3(0.8,0.8,0.8)*d;
}

vec3 refractColor(vec3 ro, vec3 rd, vec3 n, vec3 p){
    float ratio=1.0/1.4;
    float cosi = dot(-rd, n);
    float cost = 1.0 - ratio*ratio*(1.0-cosi*cosi);
    if(cost<0.0) return reflectColor(ro, rd, n, p);
    vec3 t = normalize(rd*ratio + (ratio*cosi - sqrt(abs(cost)))*n);

    vec3 sp = p + t*0.002;
    float accum=0.0;
    for(int i=0;i<40;i++){
        float d=sceneSDF(sp);
        if(d<0.0) break;
        sp += t*0.01;
        accum += 0.02;
        if(accum>1.0) break;
    }
    return mix(vec3(0.2,0.2,0.8), vec3(0.8,0.8,0.2), accum);
}

vec3 textureEnv(vec3 r){
    float a=atan(r.z,r.x);
    float u=a*0.1591+0.5;
    float v=asin(r.y)*0.3183+0.5;
    vec2 uv=vec2(u,v);
    uv.y=1.0 - uv.y;
    float c1=noise2D(uv*5.0);
    float c2=noise2D(uv*6.0);
    float c3=noise2D(uv*7.0);
    return vec3(c1,c2,c3)*0.6 + 0.4;
}

float calcAO(vec3 p, vec3 n){
    float r=0.0, w=1.0;
    for(int i=0;i<5;i++){
        float dist = float(i)*0.000002;
        float d = sceneSDF(p + n*dist + 0.00001);
        r += -(d - dist);
        w *= 0.5;
    }
    return clamp(1.0 - r*0.09, 0.0, 1.0);
}

float softShadow(vec3 ro, vec3 rd, float k){
    float res=1.0, t=0.01;
    for(int i=0;i<40;i++){
        float h=sceneSDF(ro+rd*t);
        if(h<0.001) return 0.0;
        res = min(res, k*h/t);
        t += clamp(h, 0.02, 0.1);
        if(res<0.001) break;
    }
    return res;
}

vec3 lighting(vec3 p, vec3 n, vec3 rd){
    vec3 lightPos = vec3(100.0,4500.0,-300.0);
    vec3 l = normalize(lightPos - p);
    float diff = max(dot(n,l),0.0);
    float sh = softShadow(p + 0.001*n, l, 8.0);
    diff *= sh;
    float spec = pow(max(dot(reflect(-l,n),-rd),0.0),1.0)*diff;
    float ao = calcAO(p,n);
    vec3 amb = vec3(0.401,0.2,0.2)*ao;
    vec3 col = amb + vec3(1.0,0.0,0.8)*diff + vec3(1.0)*spec*0.9;
    return col;
}

float swirlFactor(vec3 p){
    return noise3D(p*4.0+vec3(0.0,1.3,2.1))*0.5;
}

vec3 colorLollipopHead1(vec3 p){
    vec3 base = vec3(1.0,0.2,0.2);
    float sw = swirlFactor(p);
    return mix(base, vec3(0.2,1.0,0.2), sw);
}

vec3 colorStick1(vec3 p){
    vec3 c=vec3(0.8,0.8,0.7);
    float g=noise3D(p*10.0)*0.1;
    return c+g;
}

vec3 colorLollipopHead2(vec3 p){
    vec3 base=vec3(0.1,0.4,1.0);
    float sw=swirlFactor(p);
    return mix(base, vec3(1.0,1.0,0.2), sw);
}

vec3 colorStick2(vec3 p){
    vec3 c=vec3(0.6,0.6,0.9);
    float g=noise3D(p*10.0)*0.1;
    return c+g;
}

float whichObject(vec3 p){
    vec3 p2 = p - vec3(1.4,0.0,0.0);
    float h1 = lollipopHead1(p);
    float h2 = lollipopHead2(p2);
    float s1 = abs(h1);
    float s2 = abs(h2);
    float st1 = abs(lollipopStick1(p));
    float st2 = abs(lollipopStick2(p2));
    float m1 = min(s1, st1);
    float m2 = min(s2, st2);
    return (m1<m2) ? 1.0 : 2.0;
}

vec3 colorObject(vec3 p){
    float obj = whichObject(p);
    if(obj<1.5){
        float hh = lollipopHead1(p);
        float ss = lollipopStick1(p);
        if(abs(hh)<abs(ss)) return colorLollipopHead1(p);
        return colorStick1(p);
    } else {
        vec3 p2 = p - vec3(1.4,0.0,0.0);
        float hh = lollipopHead2(p2);
        float ss = lollipopStick2(p2);
        if(abs(hh)<abs(ss)) return colorLollipopHead2(p2);
        return colorStick2(p2);
    }
}

vec3 finalColor2(vec3 ro, vec3 rd, float t){
    if(t<0.0) return textureEnv(rd);
    vec3 p = ro + rd*t;
    vec3 n = calcNormal(p);
    vec3 col = lighting(p,n,rd);
    vec3 base = colorObject(p);
    vec3 reflection = reflectColor(ro, rd, n, p);
    vec3 refraction = refractColor(ro, rd, n, p);
            float fBase = 0.99999;
    float fresnel = pow(fBase - max(dot(n,-rd),0.0), 4.5);
    vec3 fcol = mix(base, reflection, 1.3*fresnel);
    vec3 refMix = mix(fcol, refraction, 0.144);
    float metalness = .58;
    vec3 f = mix(refMix, col, .1);
    float factor = 0.5+ .2*noise3D(p*0.5);
    f = mix(f, fcol, factor/metalness);
    return f;
}

vec3 cameraPos(float time){
    float r=3.2;
    float x=sin(time*0.55)*r;
    float y=1.5+0.4*sin(time*0.2);
    float z=cos(time*0.55)*r;
    return vec3(x,y,z);
}

vec3 backgroundColor(){
    return vec3(0.02,0.02,0.03);
}
vec3 finalColor(vec3 ro, vec3 rd, float t){
    if(t<0.0) return textureEnv(rd);
    vec3 p = ro + rd*t;
    vec3 n = calcNormal(p);
    vec3 col = lighting(p,n,rd);
    vec3 base = colorObject(p);
    vec3 reflection = reflectColor(ro, rd, n, p);
    vec3 refraction = refractColor(ro, rd, n, p);
    float fBase = 0.99999;
    float fresnel = pow(fBase - max(dot(n,-rd),0.0), 4.5);
    vec3 fcol = mix(base, reflection, 1.3*fresnel);
    vec3 refMix = mix(fcol, refraction, 0.144);
    float metalness = .58;
    vec3 f = mix(refMix, col, .1);
    float factor = 0.5+ .2*noise3D(p*0.5);
    f = mix(f, fcol, factor/metalness);
    return f;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float time = iTime;

    vec3 ro = cameraPos(time);
    vec3 ta = vec3(1.0, 0.0, 0.0);

    vec3 ww = normalize(ta - ro);
    vec3 up = vec3(sin(iTime) *.0001+0.0001, sin(iTime)*0.0001+0.0001, 0.0);
    vec3 uu = normalize(cross(ww, up));
    vec3 vv = cross(uu, ww);

    float lens = 2.52;
    if (iMouse.z > 0.0) {
        lens = iMouse.x/iResolution.x*3.0;
    }
    vec3 rd = normalize(uu*uv.x + vv*uv.y + ww*lens);

    float t = raymarch(ro, rd);
    vec3 col = (t<0.0) ? backgroundColor() : finalColor(ro, rd, t);

    // Нормализация t для alpha-канала
    float alpha;
    if (t < 0.0) {
        alpha = 0.0; // Фон полностью прозрачный
    } else {
        // Для конфеты (шара) используем нелинейное преобразование
        float depth = smoothstep(0.0, 20.0, t); // Нормализация t в диапазоне 0..1
        alpha = mix(0.2, 0.8, depth); // Диапазон alpha для конфеты
    }

    fragColor = vec4(pow(col, vec3(0.88545)), alpha);
}
